head.script:
// 테스트 설명, 유효성 값 설정
//  ★ mergeClear : 동적으로 병합된 Body Cell 을 모두 원래 상태로 해제 (파라미터 없음).
//     · @desc2 와 @spec2 는 의미 중복 → UT_01 규칙에 따라 1개 validation 으로 통합.
//     · @related(mergeCells 등)는 병합 setUp 용도로만 사용(검증 대상 아님).
scwin.tData = {
    "description" : "[gridView > M > mergeClear]<br/>동적으로 병합된 Body Cell 을 모두 원래 상태로 해제합니다.",
    "validation" : [
        "고정/비고정 영역의 모든 자동/수동 병합 상태를 해제합니다.",
        "메소드 실행 시 mergeCells, mergeCellsFixedRows, mergeCellsFixedCols 속성이 모두 'never' 로 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 고정/비고정 영역에 자동/수동 병합이 모두 드러나도록 구성.
//  fixedRow=1(행0 고정), fixedColumn=1(col1 고정) → 고정/비고정 영역이 모두 존재.
//
//  행 | col1(고정) | col2 | col3 | col4
//  ---+-----------+------+------+------
//   0 |  H        |  H   |  S   |  S     ← 고정 Row(행0). col1=col2=H, col3=col4=S (가로 동일값)
//   1 |  A        |  X   |  P   |  9     ← 이하 비고정 Body. col1 전부 A(세로),
//   2 |  A        |  X   |  P   |  1
//   3 |  A        |  Y   |  P   |  1
//
//  · 비고정 mergeCells("bycol") : col1[1~3]=A / col2[1~2]=X / col3[1~3]=P 세로병합.
//  · 고정 Row(행0) mergeCellsFixedRows("byrow") : 행0 col1=col2=H(가로), col3=col4=S(가로).
//  · 수동 mergeCell : 비고정 영역 임의 블록 병합.
scwin.MERGE_DATA = [
    { "col1": "H", "col2": "H", "col3": "S", "col4": "S" },
    { "col1": "A", "col2": "X", "col3": "P", "col4": "9" },
    { "col1": "A", "col2": "X", "col3": "P", "col4": "1" },
    { "col1": "A", "col2": "Y", "col3": "P", "col4": "1" }
];



// comp 생성 : fixedRow=1, fixedColumn=1 그리드 1개를 동적 생성.
//  ★ mergeCells 류 속성은 attribute 로 주지 않는다 (초기 미병합 상태로 생성 → 버튼으로 병합/해제).
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="fixedRow=1(행0 고정), fixedColumn=1(col1 고정). ① 버튼으로 자동/수동/고정 병합 설정 → ② mergeClear 로 전체 해제(3속성 never) 확인"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedRow=1(행0 고정), fixedColumn=1(col1 고정)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        fixedColumn: 1,
        fixedRow: 1,
        defaultCellHeight: 34
    });

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:380px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeClear sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1(고정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// ① 병합 생성 : 고정/비고정 자동병합 + 수동병합 설정.
//  · 비고정 자동 : mergeCells("bycol")
//  · 고정 Row 자동 : mergeCellsFixedRows("byrow")  (행0 가로 병합)
//  · 수동 : mergeCell({rowIndex,colIndex,rowSpan,colSpan})
scwin.btn_setUp_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // 비고정 자동 병합 (bycol)
    target1.mergeCells("bycol");
    // 고정 Row 자동 병합 (byrow)
    target1.mergeCellsFixedRows("byrow");
    // 수동 병합 (비고정 영역 col4 행1~행2 세로 블록 — 값(9,1)이 달라 자동병합 안 되는 영역을 수동 병합)
    target1.mergeCell({ "rowIndex": 1, "colIndex": 3, "rowSpan": 2, "colSpan": 1 });

    bottom.setReturnValue("[setUp] mergeCells('bycol') + mergeCellsFixedRows('byrow') + mergeCell 적용");
    bottom.setReturnValue("[속성] mergeCells=" + target1.options.mergeCells + " / mergeCellsFixedRows=" + target1.options.mergeCellsFixedRows + " / mergeCellsFixedCols=" + target1.options.mergeCellsFixedCols);
    scwin.printMergeState(bottom);
}



// ② mergeClear 실행 : 모든 동적 병합을 원래 상태로 해제. (파라미터 없음)
//  검증 : (1) 모든 td rowSpan/colSpan = 1 (병합 해제) / (2) 3속성 모두 'never'(@spec1)
scwin.btn_mergeClear_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.mergeClear();

    bottom.setReturnValue("호출 : target1.mergeClear()");

    // (2) @spec1 : 3속성 모두 'never'
    let mc = target1.options.mergeCells;
    let mfr = target1.options.mergeCellsFixedRows;
    let mfc = target1.options.mergeCellsFixedCols;
    bottom.setReturnValue("[속성 never] mergeCells=" + mc + " / mergeCellsFixedRows=" + mfr + " / mergeCellsFixedCols=" + mfc);
    bottom.setReturnValue("[3속성 모두 never 여부] " + (mc === "never" && mfr === "never" && mfc === "never"));

    // (1) 모든 병합 해제 여부
    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 각 Body td 의 rowSpan/colSpan 을 읽어 세로/가로/블록 병합 그룹을 출력.
//  td 셀렉터는 gid = target1.id 사용 (e.target.id 는 버튼 id 라 사용 불가).
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let mergedCnt = 0;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        if (td.offsetWidth === 0) continue;

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            mergedCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("[행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    bottom.setReturnValue("[병합 상태] 병합 그룹 " + mergedCnt + "개 (0개 = 전체 해제)");
    for (let d = 0; d < descs.length; d++) bottom.setReturnValue("  - " + descs[d]);
}
